from fastapi import APIRouter
from fastapi.responses import HTMLResponse, Response

router = APIRouter(tags=['dashboard-ui'])

HTML = '''<!doctype html><html lang="es"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="theme-color" content="#101318"><link rel="manifest" href="/manifest.webmanifest"><title>Phygital Bot</title><style>body{font-family:system-ui;background:#0b0e12;color:#eef2f7;margin:0}.w{max-width:1000px;margin:auto;padding:16px}.c{background:#151a21;border:1px solid #26303b;border-radius:14px;padding:16px;margin:12px 0}.g{display:grid;grid-template-columns:repeat(auto-fit,minmax(140px,1fr));gap:10px}input,button{width:100%;padding:12px;margin:6px 0;border-radius:10px;border:1px solid #354052}.h{display:none}.row{padding:10px 0;border-bottom:1px solid #26303b}.b{display:inline-block;padding:3px 8px;background:#26303b;border-radius:999px;font-size:12px}</style></head><body><div class="w"><section id="login" class="c"><h1>Phygital Bot</h1><input id="u" placeholder="Usuario"><input id="p" type="password" placeholder="Contraseña"><button onclick="go()">Entrar</button><div id="e"></div></section><section id="app" class="h"><h1>Dashboard</h1><div id="stats" class="g"></div><div class="c"><button onclick="help()">Solicitudes</button><button onclick="conv()">Conversaciones</button><button onclick="contacts()">Contactos</button><div id="content"></div></div></section></div><script>const k='phygital_token',h=()=>({'Authorization':'Bearer '+localStorage.getItem(k)});async function go(){let r=await fetch('/api/auth/login',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({username:u.value,password:p.value})});if(!r.ok){e.textContent='Credenciales incorrectas';return}let j=await r.json();localStorage.setItem(k,j.access_token);show()}async function api(x){let r=await fetch(x,{headers:h()});if(r.status===401){localStorage.removeItem(k);location.reload()}return r.json()}async function show(){login.classList.add('h');app.classList.remove('h');let s=await api('/api/stats');stats.innerHTML=Object.entries(s).map(x=>'<div class="c"><b>'+x[1]+'</b><div>'+x[0]+'</div></div>').join('');help()}async function help(){let a=await api('/api/help-requests');content.innerHTML='<h2>Solicitudes de ayuda</h2>'+a.map(r=>'<div class="row"><b>'+r.wa_user_id+'</b><div>'+r.body+'</div><span class="b">'+(r.known_contact?'contacto':'no agregado')+'</span> <span class="b">'+r.status+'</span></div>').join('')}async function conv(){let a=await api('/api/conversaciones');content.innerHTML='<h2>Conversaciones</h2>'+a.map(r=>'<div class="row"><b>'+r.wa_user_id+'</b> <span class="b">'+(r.known_contact?'contacto':'no agregado')+'</span><div>'+r.state+' · '+r.status+'</div></div>').join('')}async function contacts(){let a=await api('/api/contacts');content.innerHTML='<h2>Contactos</h2><p>La app Android sincronizará aquí la agenda.</p>'+a.map(r=>'<div class="row"><b>'+(r.name||'Sin nombre')+'</b><div>'+r.phone+'</div></div>').join('')}if('serviceWorker'in navigator)navigator.serviceWorker.register('/sw.js');if(localStorage.getItem(k))show();</script></body></html>'''

@router.get('/dashboard', response_class=HTMLResponse)
def dashboard(): return HTML

@router.get('/manifest.webmanifest')
def manifest(): return {'name':'Phygital Bot Dashboard','short_name':'Phygital Bot','start_url':'/dashboard','display':'standalone','background_color':'#0b0e12','theme_color':'#101318'}

@router.get('/sw.js')
def sw(): return Response("self.addEventListener('fetch',()=>{})", media_type='application/javascript')
